#include <iostream>

class Counter {
    friend std::ostream& operator<<(std::ostream& os, const Counter& c);
    friend std::istream& operator>>(std::istream& is, Counter& c);
private:
    int value{0};
public:
    Counter() = default;
    explicit Counter(int v) : value{v} {}

    // Prefix increment: ++c
    Counter& operator++() {
        ++value;
        return *this;
    }

    // Postfix increment: c++
    Counter operator++(int) {
        Counter temp = *this;
        ++value;
        return temp;
    }
};

std::ostream& operator<<(std::ostream& os, const Counter& c) {
    os << "[Count: " << c.value << "]";
    return os;
}

std::istream& operator>>(std::istream& is, Counter& c) {
    is >> c.value;
    return is;
}

int main() {
    Counter c{10};
    std::cout << "Initial: " << c << '\n';
    std::cout << "Prefix ++: " << ++c << '\n';
    std::cout << "Postfix ++: " << c++ << '\n';
    std::cout << "Final: " << c << '\n';
    return 0;
}

#include <iostream>
#include <utility>

class SimpleIntVector {
private:
    size_t size_{0};
    int* data_{nullptr};
public:
    explicit SimpleIntVector(size_t size) 
        : size_{size}, data_{new int[size]{}} {}

    ~SimpleIntVector() {
        delete[] data_;
    }

    // Copy constructor
    SimpleIntVector(const SimpleIntVector& other) 
        : size_{other.size_}, data_{new int[other.size_]} {
        for (size_t i = 0; i < size_; ++i) {
            data_[i] = other.data_[i];
        }
    }

    // Assignment operator with self-assignment guard
    SimpleIntVector& operator=(const SimpleIntVector& other) {
        if (this == &other) {
            return *this; // Self-assignment check
        }
        int* newData = new int[other.size_];
        for (size_t i = 0; i < other.size_; ++i) {
            newData[i] = other.data_[i];
        }
        delete[] data_;
        data_ = newData;
        size_ = other.size_;
        return *this;
    }

    int& operator[](size_t index) { return data_[index]; }
    int operator[](size_t index) const { return data_[index]; }
    size_t size() const { return size_; }
};

int main() {
    SimpleIntVector v1(3);
    v1[0] = 10; v1[1] = 20; v1[2] = 30;

    SimpleIntVector v2 = v1; // Copy constructor
    v1 = v1; // Self-assignment test

    std::cout << "v2[1] = " << v2[1] << '\n';
    std::cout << "v1[2] = " << v1[2] << '\n';
    return 0;
}

#include <iostream>
#include <vector>

class Matrix2D {
private:
    size_t rows_;
    size_t cols_;
    std::vector<int> data_;
public:
    Matrix2D(size_t rows, size_t cols) 
        : rows_{rows}, cols_{cols}, data_(rows * cols, 0) {}

    // Overloaded () for non-const objects (lvalue)
    int& operator()(size_t r, size_t c) {
        return data_[r * cols_ + c];
    }

    // Overloaded () for const objects (rvalue access)
    int operator()(size_t r, size_t c) const {
        return data_[r * cols_ + c];
    }

    size_t rows() const { return rows_; }
    size_t cols() const { return cols_; }
};

int main() {
    Matrix2D grid(2, 3);
    grid(0, 1) = 7;
    grid(1, 2) = 42;

    const Matrix2D& constRef = grid;
    std::cout << "grid(0, 1) = " << constRef(0, 1) << '\n';
    std::cout << "grid(1, 2) = " << constRef(1, 2) << '\n';
    return 0;
}
